# UTXO set, saldo e fee
COIN = 100_000_000  # satoshi per BTC

# UTXO set: (txid, indice) -> (valore in satoshi, proprietario)
utxo = {
    ("f5d8ee39", 1): (30_000_000, "alice"),
    ("e9cea205", 0): (40_000_000, "alice"),
    ("6cc8d26b", 0): (25_000_000, "bob"),
}

def balance(owner):
    return sum(v for (v, o) in utxo.values() if o == owner)

def apply_tx(inputs, outputs, txid):
    """inputs: lista di outpoint; outputs: lista di (valore, proprietario).
    Restituisce la fee in satoshi o solleva ValueError."""
    if len(set(inputs)) != len(inputs):
        raise ValueError("input duplicato")
    for op in inputs:
        if op not in utxo:
            raise ValueError(f"{op} inesistente o già speso")
    tot_in = sum(utxo[op][0] for op in inputs)
    tot_out = sum(v for v, _ in outputs)
    if tot_in < tot_out:
        raise ValueError("somma output > somma input")
    for op in inputs:
        del utxo[op]
    for i, out in enumerate(outputs):
        utxo[(txid, i)] = out
    return tot_in - tot_out

print("saldo alice prima:", balance("alice") / COIN, "BTC")
fee = apply_tx([("f5d8ee39", 1), ("e9cea205", 0)],
               [(50_000_000, "bob"), (19_800_000, "alice")], "c91a5917")
print("fee:", fee, "sat =", fee / COIN, "BTC")
print("saldo alice dopo:", balance("alice") / COIN, "BTC")
print("saldo bob dopo:", balance("bob") / COIN, "BTC")
try:
    apply_tx([("e9cea205", 0)], [(1_000, "carol")], "doppia")
except ValueError as e:
    print("rifiutata:", e)

