# Interprete a stack per P2PK e P2PKH con vere firme ECDSA su secp256k1
import hashlib

P = 2**256 - 2**32 - 977
N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141
G = (0x79BE667EF9DCBBAC55A06295CE870B07029BFCDB2DCE28D959F2815B16F81798,
     0x483ADA7726A3C4655DA4FBFC0E1108A8FD17B448A68554199C47D08FFB10D4B8)

def ec_add(a, b):
    if a is None: return b
    if b is None: return a
    if a[0] == b[0] and (a[1] + b[1]) % P == 0: return None
    if a == b: l = 3 * a[0] * a[0] * pow(2 * a[1], -1, P) % P
    else: l = (b[1] - a[1]) * pow(b[0] - a[0], -1, P) % P
    x = (l * l - a[0] - b[0]) % P
    return (x, (l * (a[0] - x) - a[1]) % P)

def ec_mul(k, pt=G):
    r = None
    while k:
        if k & 1: r = ec_add(r, pt)
        pt = ec_add(pt, pt); k >>= 1
    return r

def H(b): return int.from_bytes(hashlib.sha256(hashlib.sha256(b).digest()).digest(), "big")

def pubkey(sk):
    x, y = ec_mul(sk); return bytes([2 + (y & 1)]) + x.to_bytes(32, "big")

def decode_pub(pk):
    x = int.from_bytes(pk[1:], "big"); y = pow((x**3 + 7) % P, (P + 1) // 4, P)
    if y & 1 != pk[0] & 1: y = P - y
    return (x, y)

def sign(sk, msg):                      # k deterministico (didattico, non RFC6979)
    z = H(msg); k = H(sk.to_bytes(32, "big") + msg) % N
    r = ec_mul(k)[0] % N; s = pow(k, -1, N) * (z + r * sk) % N
    return r.to_bytes(32, "big") + s.to_bytes(32, "big")

def verify(pk, msg, sig):
    r, s = int.from_bytes(sig[:32], "big"), int.from_bytes(sig[32:], "big")
    if not (0 < r < N and 0 < s < N): return False
    z = H(msg); w = pow(s, -1, N)
    pt = ec_add(ec_mul(z * w % N), ec_mul(r * w % N, decode_pub(pk)))
    return pt is not None and pt[0] % N == r

def hash160(b): return hashlib.new("ripemd160", hashlib.sha256(b).digest()).digest()

def run(script, tx):
    """script: lista di bytes (dati) o str (opcode). tx: bytes firmati."""
    st = []
    for op in script:
        if isinstance(op, bytes): st.append(op); continue
        if op.startswith("OP_") and op[3:].isdigit(): st.append(int(op[3:])); continue
        if op == "OP_ADD": b, a = st.pop(), st.pop(); st.append(a + b)
        elif op == "OP_DUP": st.append(st[-1])
        elif op == "OP_HASH160": st.append(hash160(st.pop()))
        elif op in ("OP_EQUAL", "OP_EQUALVERIFY"):
            eq = st.pop() == st.pop()
            if op == "OP_EQUAL": st.append(1 if eq else 0)
            elif not eq: return False, "EQUALVERIFY fallito"
        elif op == "OP_CHECKSIG":
            pk, sig = st.pop(), st.pop(); st.append(1 if verify(pk, tx, sig) else 0)
        else: return False, "opcode sconosciuto " + op
    ok = bool(st) and st[-1] not in (0, b"")
    return ok, st[-1] if st else None

bob_sk = 0xB0B; eve_sk = 0xE7E
bob_pk, eve_pk = pubkey(bob_sk), pubkey(eve_sk)
tx = b"tx: spendi c91a5917:0 verso carol"

print("aritmetica:", run(["OP_2", "OP_3", "OP_ADD"], tx))
p2pk = [bob_pk, "OP_CHECKSIG"]
print("P2PK firma di Bob:", run([sign(bob_sk, tx)] + p2pk, tx)[0])
print("P2PK firma di Eve:", run([sign(eve_sk, tx)] + p2pk, tx)[0])
p2pkh = ["OP_DUP", "OP_HASH160", hash160(bob_pk), "OP_EQUALVERIFY", "OP_CHECKSIG"]
print("P2PKH Bob corretto:", run([sign(bob_sk, tx), bob_pk] + p2pkh, tx)[0])
print("P2PKH chiave di Eve:", run([sign(eve_sk, tx), eve_pk] + p2pkh, tx))
altra = b"tx: spendi c91a5917:0 verso eve"
print("P2PKH firma riusata su altra tx:", run([sign(bob_sk, tx), bob_pk] + p2pkh, altra)[0])

