# Algoritmo di ricezione (slide 75) su due nodi: mempool e doppia spesa
class Node:
    def __init__(self, name, utxo, check_dup=True):
        self.name, self.utxo, self.mempool = name, dict(utxo), []
        self.check_dup = check_dup

    def receive(self, t):
        ins, outs = t["in"], t["out"]
        if self.check_dup and len(set(ins)) != len(ins):
            return "scartata (input duplicato)"
        for op in ins:
            if op not in self.utxo:            # firma omessa: la supponiamo valida
                return "scartata (output inesistente o già speso)"
        if sum(self.utxo[op] for op in ins) < sum(outs):
            return "scartata (output > input)"
        for op in set(ins):
            del self.utxo[op]
        self.mempool.append(t["id"])
        return "accettata"

utxo0 = {("a1", 0): 100}                        # Alice ha un UTXO da 100
t_bob = {"id": "t_bob", "in": [("a1", 0)], "out": [95]}
t_ali = {"id": "t_alice", "in": [("a1", 0)], "out": [95]}

n1, n2 = Node("N1", utxo0), Node("N2", utxo0)
for t in (t_bob, t_ali): print("N1", t["id"], "->", n1.receive(t))
